"use client"

import { useMemo } from "react"

import { withForm } from "@/components/openlmis/form-fields/form"

import {
  EMPTY_FACILITY,
  type FacilityOption,
  toFacilityItems,
} from "@/components/blocks/openlmis/facility-general-form/facility-form"

export type FacilityLookups = {
  types: readonly FacilityOption[]
  zones: readonly FacilityOption[]
  operators: readonly FacilityOption[]
}

type FacilityFormFieldsProps = {
  lookups: FacilityLookups
  /** Managed by another system: name, code, zone, description and Active cannot change. */
  locked?: boolean
  /** Every field read only, e.g. without the right to edit facilities. */
  readOnly?: boolean
  /** A saved facility must keep its operational date. */
  goLiveDateRequired?: boolean
}

/** The facility's details in two columns once there is room, shared by Add Facility and the editor. */
export const FacilityFormFields = withForm({
  defaultValues: EMPTY_FACILITY,
  props: {} as FacilityFormFieldsProps,
  render: function Render({
    form,
    lookups,
    locked = false,
    readOnly = false,
    goLiveDateRequired = false,
  }) {
    const typeItems = useMemo(
      () => toFacilityItems(lookups.types),
      [lookups.types]
    )
    const zoneItems = useMemo(
      () => toFacilityItems(lookups.zones),
      [lookups.zones]
    )
    const operatorItems = useMemo(
      () => toFacilityItems(lookups.operators),
      [lookups.operators]
    )
    const fixed = locked || readOnly

    return (
      <div className="grid gap-x-6 gap-y-5 @3xl/main:grid-cols-2">
        <form.AppField name="name">
          {(field) => (
            <field.TextField
              autoComplete="off"
              dir="auto"
              disabled={fixed}
              label="Facility Name"
              required
            />
          )}
        </form.AppField>
        <form.AppField name="code">
          {(field) => (
            <field.TextField
              autoComplete="off"
              dir="ltr"
              disabled={fixed}
              label="Facility Code"
              required
            />
          )}
        </form.AppField>
        <form.AppField name="typeId">
          {(field) => (
            <field.ComboboxField
              clearLabel="Clear Facility Type"
              disabled={readOnly}
              emptyMessage="No Matches"
              items={typeItems}
              label="Facility Type"
              placeholder="Select A Type"
              required
            />
          )}
        </form.AppField>
        <form.AppField name="zoneId">
          {(field) => (
            <field.ComboboxField
              clearLabel="Clear Geographic Zone"
              disabled={fixed}
              emptyMessage="No Matches"
              items={zoneItems}
              label="Geographic Zone"
              limit={-1}
              placeholder="Select A Zone"
              required
            />
          )}
        </form.AppField>
        <form.AppField name="goLiveDate">
          {(field) => (
            <field.DateField
              clearLabel="Clear Operational Date"
              description="This is used in reporting to record the date the facility becomes operational."
              disabled={readOnly}
              label="Operational Date"
              placeholder="Pick A Date"
              required={goLiveDateRequired}
            />
          )}
        </form.AppField>
        <form.AppField name="operatorId">
          {(field) => (
            <field.ComboboxField
              clearLabel="Clear Facility Operator"
              disabled={readOnly}
              emptyMessage="No Matches"
              items={operatorItems}
              label="Facility Operator"
              placeholder="Select An Operator"
            />
          )}
        </form.AppField>
        <form.AppField name="description">
          {(field) => (
            <field.TextareaField
              dir="auto"
              disabled={fixed}
              label="Description"
            />
          )}
        </form.AppField>
        <div className="@3xl/main:col-start-1">
          <form.AppField name="active">
            {(field) => (
              <field.SwitchField
                description="This determines whether or not the facility can submit requisitions or receive deliveries."
                disabled={fixed}
                label="Active Facility"
              />
            )}
          </form.AppField>
        </div>
        <form.AppField name="enabled">
          {(field) => (
            <field.SwitchField
              description="On: the facility can operate. Off: the facility is permanently decommissioned."
              disabled={readOnly}
              label="Enabled"
            />
          )}
        </form.AppField>
      </div>
    )
  },
})

import { z } from "zod"

/** A facility type, zone or operator: picked by id and shown by name. */
export type FacilityOption = {
  id: string
  name: string
  /** Shown under the name in the list, e.g. a zone's level. */
  description?: string
}

/** What the facility forms show and save; map your API's facility onto it. */
export type FacilityValues = {
  name: string
  code: string
  typeId: string | null
  zoneId: string | null
  /** `yyyy-MM-dd`, or empty for none. */
  goLiveDate: string
  description: string
  operatorId: string | null
  active: boolean
  enabled: boolean
}

export const EMPTY_FACILITY: FacilityValues = {
  name: "",
  code: "",
  typeId: null,
  zoneId: null,
  goLiveDate: "",
  description: "",
  operatorId: null,
  active: true,
  enabled: true,
}

const requiredText = (message: string) =>
  z.string().refine((value) => value.trim().length > 0, message)

const requiredChoice = (message: string) =>
  z
    .string()
    .nullable()
    .refine((value) => Boolean(value), message)

const comparableCode = (code: string) => code.trim().toLowerCase()

type FacilitySchemaOptions = {
  /** Other facilities' codes, and any the server refused, turned down as this one's. */
  takenCodes?: readonly string[]
  /** A saved facility must keep an operational date. */
  goLiveDateRequired?: boolean
  /** Managed by another system: its name and code cannot change, so they are not checked. */
  locked?: boolean
}

export function facilityFormSchema({
  takenCodes = [],
  goLiveDateRequired = false,
  locked = false,
}: FacilitySchemaOptions = {}) {
  const taken = new Set(takenCodes.map(comparableCode))
  return z.object({
    name: locked ? z.string() : requiredText("Enter a name."),
    code: locked
      ? z.string()
      : requiredText("Enter a code.").refine(
          (code) => !taken.has(comparableCode(code)),
          "Another facility already has this code."
        ),
    typeId: requiredChoice("Choose a facility type."),
    zoneId: requiredChoice("Choose a geographic zone."),
    goLiveDate: goLiveDateRequired
      ? requiredText("Choose an operational date.")
      : z.string(),
    description: z.string(),
    operatorId: z.string().nullable(),
    active: z.boolean(),
    enabled: z.boolean(),
  })
}

/** The values as a save sends them: text trimmed. */
export const toFacilityValues = (values: FacilityValues): FacilityValues => ({
  ...values,
  name: values.name.trim(),
  code: values.code.trim(),
  description: values.description.trim(),
})

/** How many fields differ from the saved facility. */
export function facilityChanges(values: FacilityValues, saved: FacilityValues) {
  return (Object.keys(saved) as (keyof FacilityValues)[]).filter((key) => {
    const value = values[key]
    const before = saved[key]
    return typeof value === "string" && typeof before === "string"
      ? value.trim() !== before.trim()
      : value !== before
  }).length
}

/** Options as a combobox lists them, by name. */
export const toFacilityItems = (options: readonly FacilityOption[]) =>
  options
    .map((option) => ({
      value: option.id,
      label: option.name,
      ...(option.description && { description: option.description }),
    }))
    // oxlint-disable-next-line unicorn/no-array-sort -- sorts the new array without requiring ES2023
    .sort((a, b) => a.label.localeCompare(b.label))

"use client"

import { revalidateLogic, useStore } from "@tanstack/react-form"
import { useEffect, useId, useMemo, useRef } from "react"

import { Field, FieldGroup, FieldLabel } from "@/components/ui/field"
import { useAppForm } from "@/components/openlmis/form-fields/form"
import { FieldSkeleton } from "@/components/openlmis/form-fields/form-fields"

import {
  facilityChanges,
  facilityFormSchema,
  type FacilityValues,
  toFacilityValues,
} from "@/components/blocks/openlmis/facility-general-form/facility-form"
import {
  type FacilityLookups,
  FacilityFormFields,
} from "@/components/blocks/openlmis/facility-general-form/facility-form-fields"

type FacilityGeneralFormProps = {
  /** The facility's saved values, or `EMPTY_FACILITY` to add one; a skeleton shows until it is set. */
  facility: FacilityValues | undefined
  /** The types, zones and operators to pick from; their fields show skeletons until set. */
  lookups: FacilityLookups | undefined
  /** Other facilities' codes, and any the server refused, turned down as this one's. */
  takenCodes?: readonly string[]
  /** A saved facility must keep its operational date. */
  goLiveDateRequired?: boolean
  /** Managed by another system: name, code, zone, description and Active cannot change. */
  locked?: boolean
  readOnly?: boolean
  /** The form's id, for a Save placed elsewhere, e.g. in a page's `WorkspaceFooter`. */
  formId?: string
  /** Called with trimmed values once every field is valid. */
  onSubmit: (values: FacilityValues) => void
  /** Called when a submit finds errors, e.g. to open the tab that holds them. */
  onInvalid?: () => void
  /** Tells the page how many fields are unsaved, e.g. to ask before leaving. */
  onChangesChange?: (changes: number) => void
}

/** A facility's Information tab: name, code, type, zone, dates and status. */
export function FacilityGeneralForm({
  facility,
  lookups,
  ...props
}: FacilityGeneralFormProps) {
  if (!facility || !lookups) {
    return (
      <FacilityGeneralFormSkeleton
        goLiveDateRequired={props.goLiveDateRequired}
      />
    )
  }
  return <GeneralForm facility={facility} lookups={lookups} {...props} />
}

function GeneralForm({
  facility,
  lookups,
  takenCodes,
  goLiveDateRequired = false,
  locked = false,
  readOnly = false,
  formId: givenFormId,
  onSubmit,
  onInvalid,
  onChangesChange,
}: FacilityGeneralFormProps & {
  facility: FacilityValues
  lookups: FacilityLookups
}) {
  const generatedFormId = useId()
  const formId = givenFormId ?? generatedFormId
  // Keyed on the codes, so an inline array does not re-run validation each render.
  const takenKey = takenCodes?.join("\n") ?? ""
  const schema = useMemo(
    () =>
      facilityFormSchema({
        takenCodes: takenKey ? takenKey.split("\n") : [],
        goLiveDateRequired,
        locked,
      }),
    [takenKey, goLiveDateRequired, locked]
  )

  const form = useAppForm({
    defaultValues: facility,
    // Quiet until the first submit, then each field re-checks as it is corrected.
    validationLogic: revalidateLogic({
      mode: "submit",
      modeAfterSubmission: "change",
    }),
    validators: { onDynamic: schema },
    onSubmit: ({ value }) => onSubmit(toFacilityValues(value)),
    onSubmitInvalid: () => onInvalid?.(),
  })
  const changes = useStore(form.store, (state) =>
    facilityChanges(state.values, facility)
  )

  // Starts again only when the values differ, so an equal new object keeps the draft.
  const facilityKey = JSON.stringify(facility)
  const resetKey = useRef(facilityKey)
  useEffect(() => {
    if (resetKey.current === facilityKey) return
    resetKey.current = facilityKey
    form.reset(facility)
  }, [form, facility, facilityKey])
  // A code the server refused shows its error at once, rather than on the next submit.
  useEffect(() => {
    if (form.state.submissionAttempts === 0) return
    form.update({ ...form.options, validators: { onDynamic: schema } })
    void form.validate("change")
  }, [form, schema])
  useEffect(() => {
    onChangesChange?.(changes)
  }, [changes, onChangesChange])

  return (
    <form
      id={formId}
      noValidate
      onSubmit={(event) => {
        event.preventDefault()
        void form.handleSubmit()
      }}
    >
      <FieldGroup>
        <FacilityFormFields
          form={form}
          goLiveDateRequired={goLiveDateRequired}
          locked={locked}
          lookups={lookups}
          readOnly={readOnly}
        />
      </FieldGroup>
    </form>
  )
}

function SwitchRowSkeleton({ label }: { label: string }) {
  return (
    <Field orientation="horizontal">
      <div className="flex min-h-8 flex-1 items-center">
        <FieldLabel>{label}</FieldLabel>
      </div>
      {/* A plain element, since Skeleton owns its corner radius and the switch is round. */}
      <div className="h-4.5 w-8 shrink-0 animate-pulse rounded-full bg-muted" />
    </Field>
  )
}

/** The form as it will look, so nothing moves when the facility arrives. */
export function FacilityGeneralFormSkeleton({
  goLiveDateRequired = false,
}: {
  goLiveDateRequired?: boolean
}) {
  return (
    <div aria-busy>
      <FieldGroup>
        <div className="grid gap-x-6 gap-y-5 @3xl/main:grid-cols-2">
          <FieldSkeleton label="Facility Name" required />
          <FieldSkeleton label="Facility Code" required />
          <FieldSkeleton label="Facility Type" required />
          <FieldSkeleton label="Geographic Zone" required />
          <FieldSkeleton
            label="Operational Date"
            required={goLiveDateRequired}
          />
          <FieldSkeleton label="Facility Operator" />
          <FieldSkeleton label="Description" />
          <div className="@3xl/main:col-start-1">
            <SwitchRowSkeleton label="Active Facility" />
          </div>
          <SwitchRowSkeleton label="Enabled" />
        </div>
      </FieldGroup>
    </div>
  )
}
